<script setup lang="ts">
import PageNotice from '../components/PageNotice.vue';
import ScrollTable from '../components/ScrollTable.vue';
import { scaledPopupProps } from '../utils/scaled-popup';
import {computed,onMounted,ref} from 'vue';import {useI18n} from 'vue-i18n';import {listAuditEntries,formatJst,type AuditEntry} from '../services/audit';import OperationsError from '../components/operations/OperationsError.vue';
const {t}=useI18n();const records=ref<AuditEntry[]>([]),busy=ref(false),error=ref<unknown>(null),query=ref(''),actor=ref(''),start=ref(''),end=ref(''),selected=ref<AuditEntry|null>(null),drawer=ref(false),hasMore=ref(true);
const filtered=computed(()=>records.value.filter(entry=>{const date=formatJst(entry.occurred_at).slice(0,10);return `${entry.table_name} ${JSON.stringify(entry.entity_key)}`.toLowerCase().includes(query.value.trim().toLowerCase())&&(!actor.value||(entry.application_actor_id||'').includes(actor.value))&&(!start.value||date>=start.value)&&(!end.value||date<=end.value)}));
const columns=computed(()=>[{colKey:'occurred_at',title:t('ops.audit.time'),width:180},{colKey:'table_name',title:t('ops.api.table'),width:170},{colKey:'operation',title:t('ops.api.operation'),width:120},{colKey:'application_actor_id',title:t('ops.api.actor'),width:190},{colKey:'entity_key',title:t('ops.api.entity')},{colKey:'details',title:t('ops.details'),width:80}]);
async function load(more=false){busy.value=true;error.value=null;try{const result=await listAuditEntries(more?records.value.at(-1)?.id:undefined);records.value=more?[...records.value,...result.items]:result.items;hasMore.value=result.items.length===50}catch(e){error.value=e;if(!more)records.value=[]}finally{busy.value=false}}
function show(entry:AuditEntry){selected.value=entry;drawer.value=true}onMounted(()=>load());
</script>
<template><div class="page-stack module-page"><OperationsError :error="error"/><PageNotice notification theme="info" :message="t('ops.api.auditHint')"/><t-card :title="t('ops.api.audit')" :bordered="false" class="section-card list-card"><div class="table-toolbar"><div class="filter-field"><label>{{t('ops.audit.object')}}</label><t-input v-model="query" clearable/></div><div class="filter-field"><label>{{t('ops.api.actor')}}</label><t-input v-model="actor" clearable/></div><div class="filter-field"><label>{{t('ops.audit.startDate')}} JST</label><t-date-picker :popup-props="scaledPopupProps" v-model="start" value-type="YYYY-MM-DD" clearable/></div><div class="filter-field"><label>{{t('ops.audit.endDate')}} JST</label><t-date-picker :popup-props="scaledPopupProps" v-model="end" value-type="YYYY-MM-DD" clearable/></div><t-button :loading="busy" variant="outline" @click="load()">{{t('ops.api.refresh')}}</t-button></div><PageNotice v-if="start&&end&&end<start" theme="error" :message="t('ops.audit.dateError')"/><ScrollTable row-key="id" :data="filtered" :columns="columns" :empty="t('ops.api.empty')" hover><template #occurred_at="{row}">{{formatJst(row.occurred_at)}}</template><template #application_actor_id="{row}"><span class="mono">{{row.application_actor_id||'—'}}</span></template><template #entity_key="{row}"><span class="mono">{{JSON.stringify(row.entity_key)}}</span></template><template #details="{row}"><t-link theme="primary" @click="show(row)">{{t('ops.details')}}</t-link></template></ScrollTable><div class="audit-more"><t-button :disabled="!hasMore||busy" variant="outline" @click="load(true)">{{t('ops.api.more')}}</t-button></div></t-card><t-drawer v-model:visible="drawer" :header="t('ops.audit.detail')" size="560px" :footer="false" :close-btn="true"><t-descriptions v-if="selected" :column="1"><t-descriptions-item :label="t('ops.api.id')">{{selected.id}}</t-descriptions-item><t-descriptions-item :label="t('ops.audit.time')">{{formatJst(selected.occurred_at)}}</t-descriptions-item><t-descriptions-item :label="t('ops.api.actor')"><span class="mono">{{selected.application_actor_id||'—'}}</span></t-descriptions-item><t-descriptions-item :label="t('ops.api.table')">{{selected.table_name}}</t-descriptions-item><t-descriptions-item :label="t('ops.api.operation')">{{selected.operation}}</t-descriptions-item><t-descriptions-item :label="t('ops.api.correlation')"><span class="mono">{{selected.correlation_id||'—'}}</span></t-descriptions-item><t-descriptions-item :label="t('ops.api.entity')"><pre>{{JSON.stringify(selected.entity_key,null,2)}}</pre></t-descriptions-item><t-descriptions-item :label="t('ops.api.fields')"><pre>{{JSON.stringify(selected.changed_fields,null,2)}}</pre></t-descriptions-item><t-descriptions-item :label="t('ops.api.details')"><pre>{{JSON.stringify(selected.details,null,2)}}</pre></t-descriptions-item></t-descriptions></t-drawer></div></template>
<style scoped>.mono,pre{overflow-wrap:anywhere;white-space:pre-wrap;word-break:break-word}pre{margin:0}.audit-more{display:flex;justify-content:center;margin-top:24px}</style>
